/*!
 * ScrollTrigger 3.12.5 shim para Cotillón Bambinos
 * Para producción reemplazá con:
 * https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.5/ScrollTrigger.min.js
 */
(function(w){
  'use strict';
  var instances=[];
  var ST={
    create:function(cfg){
      var trigger=cfg.trigger;
      var el=typeof trigger==='string'?document.querySelector(trigger):trigger;
      if(!el)return{kill:function(){}};
      var fired=false;
      var io=new IntersectionObserver(function(entries){
        entries.forEach(function(e){
          if(e.isIntersecting&&!fired){
            fired=true;
            if(cfg.onEnter)cfg.onEnter();
          } else if(!e.isIntersecting&&fired&&cfg.onLeaveBack){
            cfg.onLeaveBack();
          }
        });
      },{threshold:cfg.threshold||0.1,rootMargin:cfg.rootMargin||'0px'});
      io.observe(el);
      var inst={kill:function(){io.disconnect();},refresh:function(){}};
      instances.push(inst);
      return inst;
    },
    batch:function(targets,cfg){
      var els=typeof targets==='string'?
        Array.from(document.querySelectorAll(targets)):
        (Array.isArray(targets)?targets:[targets]);
      els.forEach(function(el){
        var c=Object.assign({},cfg,{
          trigger:el,
          onEnter:function(){if(cfg.onEnter)cfg.onEnter([el]);}
        });
        ST.create(c);
      });
    },
    refresh:function(){},
    defaults:function(){return ST;},
    config:function(){return ST;},
    getAll:function(){return instances;},
    killAll:function(){instances.forEach(function(i){i.kill();});instances=[];},
    scrollerProxy:function(){}
  };
  w.ScrollTrigger=ST;
  if(w.gsap&&w.gsap.registerPlugin)w.gsap.registerPlugin(ST);
})(window);
